<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$customer=customer_required();$id=max(0,scalar_int($_GET['id']??0));$stmt=db()->prepare('SELECT r.*,o.order_number,o.id order_id FROM return_requests r JOIN orders o ON o.id=r.order_id WHERE r.id=? AND r.customer_id=?');$stmt->execute([$id,(int)$customer['id']]);$return=$stmt->fetch();if(!$return){http_response_code(404);exit('درخواست پیدا نشد.');}$items=return_items_for_request($id);$refundsStmt=db()->prepare("SELECT * FROM refund_transactions WHERE return_id=? ORDER BY id DESC");$refundsStmt->execute([$id]);$refunds=$refundsStmt->fetchAll();$pageKey='account';$pageTitle='مرجوعی '.$return['return_number'].' | '.setting('store_name');$robots='noindex,nofollow';$headExtra='<link rel="stylesheet" href="'.e(asset('css/account-responsive.css')).'">';require BASE_PATH.'/app/views/header.php';?>
<main class="account-detail-page"><div class="container product-page">
<div class="public-page-title"><div><span class="eyebrow-dark">پیگیری مرجوعی</span><h1><?=e($return['return_number'])?></h1><p class="muted">وضعیت: <?=e(return_status_label($return['status']))?></p></div><div class="public-page-actions"><a class="btn btn-secondary" href="<?=e(app_url('account-order.php?id='.(int)$return['order_id']))?>">مشاهده سفارش</a></div></div>
<div class="order-meta"><div><strong>تاریخ درخواست</strong><br><?=e(jalali_format($return['created_at']))?></div><div><strong>دلیل</strong><br><?=e(return_reason_options()[$return['reason']]??$return['reason'])?></div><div><strong>مبلغ درخواستی</strong><br><?=fa_number(format_price($return['requested_amount']))?> تومان</div><div><strong>مبلغ تأییدشده</strong><br><?=fa_number(format_price($return['approved_amount']))?> تومان</div></div>
<div class="table-wrap public-table-gap"><table class="responsive-table"><thead><tr><th>کالا</th><th>تعداد</th><th>وضعیت کالا</th><th>مبلغ تأییدشده</th></tr></thead><tbody><?php foreach($items as $item):$optionLabel=order_item_option_label($item);?><tr><td data-label="کالا"><?=e($item['title'])?><?php if($optionLabel!==''):?><br><small><?=e($optionLabel)?></small><?php endif?></td><td data-label="تعداد"><?=fa_number($item['quantity'])?></td><td data-label="وضعیت کالا"><?=e(return_condition_options()[$item['condition_status']]??$item['condition_status'])?></td><td data-label="مبلغ تأییدشده"><?=fa_number(format_price($item['approved_amount']))?> تومان</td></tr><?php endforeach?></tbody></table></div>
<?php if($return['customer_note']):?><div class="checkout-card"><h2>توضیحات شما</h2><p><?=nl2br(e($return['customer_note']))?></p></div><?php endif?>
<?php if($return['admin_note']):?><div class="checkout-card"><h2>پاسخ فروشگاه</h2><p><?=nl2br(e($return['admin_note']))?></p></div><?php endif?>
<?php if($refunds):?><div class="checkout-card"><h2>بازپرداخت‌ها</h2><div class="table-wrap"><table class="responsive-table"><thead><tr><th>مبلغ</th><th>روش</th><th>مرجع</th><th>تاریخ</th></tr></thead><tbody><?php foreach($refunds as $r):?><tr><td data-label="مبلغ"><?=fa_number(format_price($r['amount']))?> تومان</td><td data-label="روش"><?=e(refund_method_options()[$r['method']]??$r['method'])?></td><td data-label="مرجع" dir="ltr"><?=e($r['reference_id']?:'—')?></td><td data-label="تاریخ"><?=e(jalali_format($r['processed_at']?:$r['created_at']))?></td></tr><?php endforeach?></tbody></table></div></div><?php endif?>
</div></main><?php require BASE_PATH.'/app/views/footer.php';
